   217	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
   218	export async function releaseDedicatedIp(serverId: string): Promise<void> {
   219	  if (SANDBOX) return;
   220	  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
   221	  if (!ip) return;
   222	  if (ovhConfigured() && ip.virtualMac) {
   223	    try {
   224	      // Remove the IP from the vMAC, then delete the vMAC.
   225	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
   226	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
   227	    } catch {
   228	      /* best-effort */
   229	    }
   230	  }
   231	  await db.dedicatedIp.update({
   232	    where: { id: ip.id },
   233	    data: { status: "FREE", serverId: null, virtualMac: null },
   234	  });
   235	}
