  1	/**
  2	 * Shared per-server DISK EXPANSION core — the money path for growing a single
  3	 * server's OWN root disk without touching its plan's CPU/RAM/price.
  4	 *
  5	 * Used by the wallet flow (lib/actions-disk.ts expandServerDisk) and by the
  6	 * Stripe confirm route so a paid checkout can apply the expansion immediately.
  7	 * Plain server module (NOT "use server") — same shape as lib/resize.ts, and it
  8	 * deliberately mirrors that file line-for-line so the two money paths can never
  9	 * drift apart.
 10	 *
 11	 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
 12	 * There is no shrink counterpart to `applyDiskExpand`, and nothing here (or
 13	 * anywhere else) ever decrements `Server.extraDiskGB`.
 14	 *
 15	 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
 16	 *  1. `diskExpandQuote` is the ONLY place the prorated amount is computed, and
 17	 *     both the wallet path and the Stripe-confirm path call it.
 18	 *  2. The wallet is debited exactly once, inside the same $transaction that
 19	 *     creates the DISK_EXPAND job — a rolled-back debit leaves no job, and a
 20	 *     job that exists was always paid for.
 21	 *  3. On the card path the wallet is NOT touched until Stripe clears: checkout
 22	 *     charges only the card remainder, the confirm route credits that remainder
 23	 *     to the wallet and then debits the FULL proration, so the two net out.
 24	 *  4. `creditCheckoutSession`'s UNIQUE(stripeSessionId) makes the confirm route
 25	 *     idempotent — a reloaded/replayed confirm URL credits (and therefore
 26	 *     applies) nothing a second time.
 27	 *  5. `Server.extraDiskGB` is advanced by the WORKER on success, never here, so
 28	 *     a failed expansion is refunded by the worker's reconcile pass and the
 29	 *     customer never renews on storage they didn't get.
 30	 */
 31	import { db } from "./db";
 32	import { debitWallet, InsufficientBalanceError } from "./wallet";
 33	import { invoiceCreateData } from "./invoices";
 34	import { getSettingInt } from "./settings";
 35	import { diskCapacityCheck } from "./capacity";
 36	import { remainingMonths } from "./proration";
 37	import {
 38	  EXTRA_DISK_DEFAULT_PER_GB_CENTS,
 39	  EXTRA_DISK_MAX_TOTAL_GB,
 40	  EXTRA_DISK_MIN_GB,
 41	  EXTRA_DISK_STEP_GB,
 42	  effectiveDiskGB,
 43	  extraDiskCentsAt,
 44	  extraDiskLabel,
 45	  extraDiskProrateCents,
 46	  isValidExtraDiskAddGB,
 47	} from "./extra-disk";
 48	
 49	export class DiskExpandError extends Error {}
 50	
 51	/**
 52	 * The per-GB/month price actually charged, from the admin setting
 53	 * (`extra_disk_gb_price_cents`, default 10 = $0.10/GB/mo). Single source of
 54	 * truth for every order/expansion/renewal/display path so they can't disagree.
 55	 */
 56	export async function extraDiskPerGbCents(): Promise<number> {
 57	  const v = await getSettingInt("extra_disk_gb_price_cents", EXTRA_DISK_DEFAULT_PER_GB_CENTS);
 58	  return Math.max(0, Math.round(v));
 59	}
 60	
 61	/** Monthly charge (integer cents) for `gb` GB of extra disk at the current price. */
 62	export async function extraDiskMonthlyCents(gb: number): Promise<number> {
 63	  if (!gb || gb <= 0) return 0;
 64	  return extraDiskCentsAt(gb, await extraDiskPerGbCents());
 65	}
 66	
 67	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
 68	
 69	function loadServer(serverId: string) {
 70	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
 71	}
 72	
 73	export type DiskExpandQuote = {
 74	  server: QuotedServer;
 75	  /** GB being added in THIS purchase. */
 76	  addGB: number;
 77	  /** `extraDiskGB` the server will hold once the worker finishes. */
 78	  targetExtraDiskGB: number;
 79	  /** Effective disk (plan + extra) after the expansion. */
 80	  newTotalDiskGB: number;
 81	  perGbCents: number;
 82	  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
 83	  monthlyCents: number;
 84	  /** One-off charge for the remainder of the CURRENT paid term. */
 85	  prorateCents: number;
 86	};
 87	
 88	/**
 89	 * Validate an expansion and compute the prorated charge over the ACTUAL
 90	 * remaining duration — identical maths to `resizeQuote` (monthly cost × every
 91	 * remaining month; null expiresAt on free/admin servers => 0). Throws
 92	 * DiskExpandError with a user-facing message on any guard failure. Does NOT
 93	 * check ownership — callers must do that.
 94	 */
 95	export async function diskExpandQuote(serverId: string, addGB: number): Promise<DiskExpandQuote> {
 96	  const server = await loadServer(serverId);
 97	  if (!server) throw new DiskExpandError("Not found");
 98	  if (!isValidExtraDiskAddGB(addGB)) {
 99	    throw new DiskExpandError(
100	      `Choose between ${EXTRA_DISK_MIN_GB} and 500 GB, in ${EXTRA_DISK_STEP_GB} GB steps.`,
101	    );
102	  }
103	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
104	    throw new DiskExpandError("Server is busy — wait for the current operation to finish.");
105	  }
106	  if (!server.vmid) throw new DiskExpandError("This server hasn't finished provisioning yet.");
107	
108	  const targetExtraDiskGB = server.extraDiskGB + addGB;
109	  const newTotalDiskGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
110	  if (newTotalDiskGB > EXTRA_DISK_MAX_TOTAL_GB) {
111	    throw new DiskExpandError(
112	      `A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — this would take it to ${newTotalDiskGB} GB. Contact support for larger volumes.`,
113	    );
114	  }
115	
116	  // Don't sell space the node can't physically back.
117	  const cap = await diskCapacityCheck(server.nodeId, addGB);
118	  if (!cap.ok) throw new DiskExpandError(cap.reason ?? "Not enough storage available right now.");
119	
120	  const perGbCents = await extraDiskPerGbCents();
121	  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
122	
123	  // The remaining-term maths comes from the two SHARED functions the "Add storage"
124	  // control also calls, so the figure the customer agreed to and the figure debited
125	  // here cannot be two different derivations of the same idea. This block used to
126	  // inline both — its own `remainingMonths` expression over a second copy of
127	  // `MS_PER_AVG_MONTH` re-exported from lib/resize.ts.
128	  let prorateCents = 0;
129	  if (!server.isFree && server.expiresAt) {
130	    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
131	  }
132	  return { server, addGB, targetExtraDiskGB, newTotalDiskGB, perGbCents, monthlyCents, prorateCents };
133	}
134	
135	/**
136	 * Apply the expansion: (optionally) debit the wallet for the prorated charge,
137	 * record the wallet transaction + PAID invoice, and queue the DISK_EXPAND job the
138	 * worker performs on Proxmox + inside the guest. Re-validates every guard (size,
139	 * ceiling, steady state, one in-flight job) so it is safe to call from the
140	 * unauthenticated confirm route. Throws DiskExpandError on any guard failure.
141	 *
142	 * `chargeCents` overrides the recomputed proration — the paid path passes the
143	 * exact amount the customer paid into their wallet at checkout so the debit here
144	 * nets to zero against that credit (mirrors lib/resize.ts applyResize).
145	 *
146	 * NOTE: `Server.extraDiskGB` is deliberately NOT advanced here. The worker sets it
147	 * only after the disk really grew, so a failed job is refunded (see
148	 * reconcileFailedJob) and no renewal ever bills for space that wasn't delivered.
149	 */
150	export async function applyDiskExpand(opts: {
151	  serverId: string;
152	  addGB: number;
153	  actorUserId: string;
154	  chargeCents?: number;
155	}): Promise<void> {
156	  const quote = await diskExpandQuote(opts.serverId, opts.addGB);
157	  const { server, addGB, targetExtraDiskGB, newTotalDiskGB, monthlyCents } = quote;
158	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
159	
160	  const pending = await db.job.count({
161	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
162	  });
163	  if (pending > 0) throw new DiskExpandError("Another operation is already in progress on this server.");
164	
165	  const label = extraDiskLabel(addGB);
166	  try {
167	    await db.$transaction(async (tx) => {
168	      if (prorateCents > 0) {
169	        await debitWallet(tx, server.userId, prorateCents);
170	        await tx.walletTransaction.create({
171	          data: {
172	            userId: server.userId,
173	            amountCents: -prorateCents,
174	            description: `${label} (prorated) — ${server.hostname}`,
175	          },
176	        });
177	        // PAID invoice for the proration. The line item spells out BOTH the
178	        // permanence and the recurring monthly cost, so the billing document
179	        // itself carries the one-way warning.
180	        await tx.invoice.create({
181	          data: invoiceCreateData({
182	            userId: server.userId,
183	            description: `${label} (prorated) — ${server.hostname}`,
184	            status: "PAID",
185	            lineItems: [
186	              {
187	                description:
188	                  `${label} — prorated for remaining term (${server.hostname}). ` +
189	                  `Disk grows to ${newTotalDiskGB} GB permanently; renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
190	                qty: 1,
191	                unitCents: prorateCents,
192	                amountCents: prorateCents,
193	              },
194	            ],
195	          }),
196	        });
197	      }
198	      // Record the amount charged AND the target on the job so the worker can
199	      // (a) know how far to grow and (b) REVERSE the charge if the expansion
200	      // terminally fails — money is committed here, before the job runs.
201	      await tx.job.create({
202	        data: {
203	          type: "DISK_EXPAND",
204	          serverId: server.id,
205	          payload: { addGB, targetExtraDiskGB, prorateCents, monthlyCents } as any,
206	        },
207	      });
208	      await tx.auditLog.create({
209	        data: {
210	          userId: opts.actorUserId,
211	          action: "server.disk_expand",
212	          detail: `${server.id} +${addGB}GB -> extra=${targetExtraDiskGB} total=${newTotalDiskGB} prorate=${prorateCents}`,
213	        },
214	      });
215	    });
216	  } catch (e) {
217	    if (e instanceof InsufficientBalanceError) {
218	      throw new DiskExpandError("Insufficient balance — top up your wallet first.");
219	    }
220	    throw e;
221	  }
222	}

  1	/**
  2	 * Mid-term BACKUP TIER upgrade — the money path for raising ONE server's backup
  3	 * RETENTION tier (FREE keep 2 -> PLUS keep 7) without touching its plan.
  4	 *
  5	 * Deliberately mirrors lib/disk-expand.ts line-for-line so the two paid-upgrade
  6	 * money paths cannot drift apart:
  7	 *   - `backupUpgradeQuote` is the ONLY place the prorated amount is computed, and
  8	 *     both the display (server page card) and the charge (applyBackupUpgrade) call
  9	 *     it, so the figure shown === the figure debited.
 10	 *   - `applyBackupUpgrade` debits the wallet and applies the tier inside ONE
 11	 *     $transaction: a rolled-back debit leaves the tier unchanged, and a tier that
 12	 *     was applied was always paid for. It re-checks the current tier INSIDE the tx
 13	 *     before debiting, so a double-submit can never double-charge.
 14	 *
 15	 * Two deliberate differences from disk-expand:
 16	 *   1. WALLET-ONLY in the MVP (no Stripe mid-term checkout route — deferred to the
 17	 *      full build). A customer with no balance can still buy Plus on card at ORDER
 18	 *      time through lib/order.ts.
 19	 *   2. NO worker job. Unlike growing a disk, retention is just a column the next
 20	 *      scheduled prune reads (worker/index.ts backupCreate), so the tier is applied
 21	 *      inline and takes effect on the next backup — nothing to reconcile.
 22	 *
 23	 * UPGRADE-ONLY: there is no downgrade path (baseline FREE is never taken away and no
 24	 * refund logic exists here). Game servers are REJECTED — renewalCharge prices a game
 25	 * plan as flat all-in with NO add-on lines, so granting one a paid tier would sell a
 26	 * tier the renewal engine never bills (the "never grant a paid tier without payment"
 27	 * invariant, in reverse).
 28	 */
 29	import { db } from "./db";
 30	import { debitWallet, InsufficientBalanceError } from "./wallet";
 31	import { invoiceCreateData } from "./invoices";
 32	import { getSettingInt } from "./settings";
 33	import { remainingMonths } from "./proration";
 34	import {
 35	  type BackupTier,
 36	  BACKUP_PLUS_DEFAULT_PRICE_CENTS,
 37	  backupTierMonthlyCents,
 38	  backupTierSpec,
 39	} from "./backup-tiers";
 40	
 41	export class BackupUpgradeError extends Error {}
 42	
 43	/**
 44	 * The Plus monthly price actually charged, from the admin setting
 45	 * (`backup_plus_price_cents`, default 299 = $2.99/mo). Single source of truth for
 46	 * the order-time upsell, this mid-term upgrade and every renewal, so they cannot
 47	 * disagree.
 48	 */
 49	export async function backupPlusMonthlyCents(): Promise<number> {
 50	  const v = await getSettingInt("backup_plus_price_cents", BACKUP_PLUS_DEFAULT_PRICE_CENTS);
 51	  return Math.max(0, Math.round(v));
 52	}
 53	
 54	function loadServer(serverId: string) {
 55	  return db.server.findUnique({ where: { id: serverId } });
 56	}
 57	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
 58	
 59	export type BackupUpgradeQuote = {
 60	  server: QuotedServer;
 61	  targetTier: BackupTier;
 62	  /** Resolved retention the tier grants. */
 63	  keep: number;
 64	  /** Recurring monthly cost of the tier (billed every renewal). */
 65	  monthlyCents: number;
 66	  /** One-off charge for the remainder of the CURRENT paid term (0 for free/admin). */
 67	  prorateCents: number;
 68	};
 69	
 70	/**
 71	 * Validate an upgrade and compute the prorated charge over the ACTUAL remaining
 72	 * term — identical maths to diskExpandQuote (monthly cost x every remaining month;
 73	 * null expiresAt on free/admin servers => 0). Throws BackupUpgradeError on any guard
 74	 * failure. Does NOT check ownership — callers must.
 75	 */
 76	export async function backupUpgradeQuote(
 77	  serverId: string,
 78	  targetTier: BackupTier,
 79	): Promise<BackupUpgradeQuote> {
 80	  const server = await loadServer(serverId);
 81	  if (!server) throw new BackupUpgradeError("Not found");
 82	  if (server.gamePlanId) {
 83	    throw new BackupUpgradeError("Backup tiers aren't available for game servers yet.");
 84	  }
 85	  if (targetTier !== "PLUS") throw new BackupUpgradeError("That backup tier isn't available.");
 86	  if (server.backupTier === targetTier) {
 87	    throw new BackupUpgradeError("This server is already on that backup tier.");
 88	  }
 89	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
 90	    throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
 91	  }
 92	
 93	  const spec = backupTierSpec(targetTier);
 94	  const monthlyCents = backupTierMonthlyCents(targetTier, await backupPlusMonthlyCents());
 95	  // Remaining-term maths from the SHARED lib/proration.ts helper (same as
 96	  // extraDiskProrateCents) so the card's figure and this debit are one derivation.
 97	  let prorateCents = 0;
 98	  if (!server.isFree && server.expiresAt) {
 99	    prorateCents = Math.max(0, Math.round(monthlyCents * remainingMonths(server.expiresAt, Date.now())));
100	  }
101	  return { server, targetTier, keep: spec.keep, monthlyCents, prorateCents };
102	}
103	
104	/**
105	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
106	 * the wallet transaction + PAID invoice, and stamp the tier + resolved retention on
107	 * the server — all in ONE $transaction. `chargeCents` overrides the recomputed
108	 * proration for a caller that already collected an exact amount (parity with
109	 * applyDiskExpand, unused in the wallet-only MVP). Throws BackupUpgradeError on any
110	 * guard failure or insufficient balance.
111	 */
112	export async function applyBackupUpgrade(opts: {
113	  serverId: string;
114	  targetTier: BackupTier;
115	  actorUserId: string;
116	  chargeCents?: number;
117	}): Promise<void> {
118	  const quote = await backupUpgradeQuote(opts.serverId, opts.targetTier);
119	  const { server, targetTier, keep, monthlyCents } = quote;
120	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
121	  const spec = backupTierSpec(targetTier);
122	  const label = `${spec.label} backups (keep ${keep})`;
123	
124	  try {
125	    await db.$transaction(async (tx) => {
126	      // Re-read the tier INSIDE the tx before any money moves: two concurrent
127	      // upgrades (a double-click) both quote FREE, but only the first commits PLUS;
128	      // the second sees PLUS here and aborts before debiting — no double charge.
129	      const fresh = await tx.server.findUnique({
130	        where: { id: server.id },
131	        select: { backupTier: true, status: true },
132	      });
133	      if (!fresh) throw new BackupUpgradeError("Not found");
134	      if (fresh.backupTier === targetTier) {
135	        throw new BackupUpgradeError("This server is already on that backup tier.");
136	      }
137	      if (!["RUNNING", "STOPPED"].includes(fresh.status)) {
138	        throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
139	      }
140	
141	      if (prorateCents > 0) {
142	        await debitWallet(tx, server.userId, prorateCents);
143	        await tx.walletTransaction.create({
144	          data: {
145	            userId: server.userId,
146	            amountCents: -prorateCents,
147	            description: `${label} (prorated) — ${server.hostname}`,
148	          },
149	        });
150	        await tx.invoice.create({
151	          data: invoiceCreateData({
152	            userId: server.userId,
153	            description: `${label} (prorated) — ${server.hostname}`,
154	            status: "PAID",
155	            lineItems: [
156	              {
157	                description:
158	                  `${label} — prorated for remaining term (${server.hostname}). ` +
159	                  `Renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
160	                qty: 1,
161	                unitCents: prorateCents,
162	                amountCents: prorateCents,
163	              },
164	            ],
165	          }),
166	        });
167	      }
168	      // Apply the tier + resolved retention, and make sure backups actually RUN —
169	      // retention is meaningless without a schedule, so bridge to the columns the
170	      // scheduler (worker/backup-schedule.ts) reads, exactly as the order path does.
171	      await tx.server.update({
172	        where: { id: server.id },
173	        data: {
174	          backupTier: targetTier,
175	          backupKeep: keep,
176	          autoBackup: true,
177	          backupIntervalHours: spec.intervalHours,
178	        },
179	      });
180	      await tx.auditLog.create({
181	        data: {
182	          userId: opts.actorUserId,
183	          action: "server.backup_upgrade",
184	          detail: `${server.id} -> ${targetTier} keep=${keep} prorate=${prorateCents}`,
185	        },
186	      });
187	    });
188	  } catch (e) {
189	    if (e instanceof InsufficientBalanceError) {
190	      throw new BackupUpgradeError("Insufficient balance — top up your wallet first.");
191	    }
192	    throw e;
193	  }
194	}

